def find_most_frequent_artist(songs):
    artist_counts = {}
    for song in songs:
        artist = song["artist"]
        artist_counts[artist] = artist_counts.get(artist, 0) + 1

    most_frequent_artists = []
    for artist, count in artist_counts.items():
        if count > len(most_frequent_artists) or (count == len(most_frequent_artists) and artist not in most_frequent_artists):
            most_frequent_artists = [artist]
        elif count == len(most_frequent_artists):
            most_frequent_artists.append(artist)

    if len(most_frequent_artists) == 1:
        return most_frequent_artists[0]
    else:
        return most_frequent_artists

