def find_highest_average_sales(brands):
    highest_average = 0
    highest_brand = None

    for brand in brands:
        sales = brand['sales']
        average_sales = sum(sales) / len(sales)
        if average_sales > highest_average:
            highest_average = average_sales
            highest_brand = brand['brand']

    return highest_brand

